252	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
253	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
254	
255	    /**
256	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
257	     * code are kept when present; otherwise country code '+61' is assumed and a single
258	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
259	     * stripped. The result must be a '+' followed by 8 to 15 digits.
260	     * Returns {@code null} when the number cannot form a valid E.164 value.
261	     */
262	    private static String normalizeTelephone(String telephone) {
263	        if (telephone == null) {
264	            return null;
265	        }
266	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
267	        String e164;
268	        if (cleaned.startsWith("+")) {
269	            e164 = cleaned;
270	        } else {
271	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
272	            e164 = "+61" + national;
273	        }
274	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
275	    }
276	
277	    /**
278	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
279	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
280	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
281	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
282	     */
283	    private String generateCustomerCode(String city, String lastName) {
284	        String city3 = firstThreeLetters(city);
285	        String last3 = firstThreeLetters(lastName);
286	        int sequence = countOwnersInCity(city) + 1;
287	        return String.format("%s-%s-%04d", city3, last3, sequence);
288	    }
289	
290	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
291	    private static String firstThreeLetters(String value) {
292	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
293	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
294	    }
295	
296	    /**
297	     * The number of existing owners registered in {@code city}, compared case-insensitively
298	     * with collapsed whitespace.
299	     */
300	    private int countOwnersInCity(String city) {
301	        String normalized = normalizeHouseholdField(city);
302	        return (int) this.clinicService.findAllOwners().stream()
303	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
304	            .count();
305	    }
306	
307	    /**
308	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
309	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
310	     */
311	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
312	        String yy = String.format("%02d", registrationDate.getYear() % 100);
313	        return customerCode + "-M" + yy;
314	    }
315	
316	    /**
317	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
318	     * last name, compared case-insensitively.
319	     */
320	    private int countNamesakes(Owner owner) {
321	        String firstName = normalizeHouseholdField(owner.getFirstName());
322	        String lastName = normalizeHouseholdField(owner.getLastName());
323	        return (int) this.clinicService.findAllOwners().stream()
324	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
325	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
326	            .count();
327	    }
328	
329	    /** Whether any existing owner already uses the given (E.164) telephone number. */
330	    private boolean isTelephoneInUse(String telephone) {
331	        return this.clinicService.findAllOwners().stream()
332	            .map(Owner::getTelephone)
333	            .filter(existing -> existing != null)
334	            .map(OwnerRestControllerV1::normalizeTelephone)
335	            .filter(existing -> existing != null)
336	            .anyMatch(telephone::equals);
337	    }
338	
339	    /** Common street-type abbreviations expanded during address normalization. */
340	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
341	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
342	
343	    /**
344	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
345	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
346	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
347	     * string when {@code address} is null or blank after normalization.
348	     */
349	    private static String normalizeAddress(String address) {
350	        if (address == null) {
351	            return "";
352	        }
353	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
354	        if (collapsed.isEmpty()) {
355	            return "";
356	        }
357	        StringBuilder sb = new StringBuilder(collapsed.length());
358	        for (String token : collapsed.split(" ")) {
359	            if (sb.length() > 0) {
360	                sb.append(' ');
361	            }
362	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
363	        }
364	        return sb.toString();
365	    }
366	
367	    /**
368	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
369	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
370	     */
371	    private static String normalizeHouseholdField(String value) {
372	        if (value == null) {
373	            return "";
374	        }
375	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
376	    }
377	
378	    /**
379	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
380	     * same address compared case-insensitively with collapsed whitespace.
381	     */
382	    private List<Owner> findHousemates(Owner owner) {
383	        String lastName = normalizeHouseholdField(owner.getLastName());
384	        String address = normalizeHouseholdField(owner.getAddress());
385	        return this.clinicService.findAllOwners().stream()
386	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
387	                && normalizeHouseholdField(existing.getAddress()).equals(address))
388	            .toList();
389	    }
390	
391	    /**
392	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
393	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
394	     */
395	    private boolean isHouseholdInUse(Owner owner) {
396	        return !findHousemates(owner).isEmpty();
397	    }
398	
399	    /**
400	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
401	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
402	     * deterministically from those normalized fields so housemates always resolve to the same value,
403	     * regardless of registration order.
404	     */
405	    private static String householdId(Owner owner) {
406	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
407	            + normalizeHouseholdField(owner.getAddress());
408	        try {
409	            byte[] digest = MessageDigest.getInstance("SHA-256")
410	                .digest(key.getBytes(StandardCharsets.UTF_8));
411	            StringBuilder sb = new StringBuilder(24);
412	            for (int i = 0; i < 12; i++) {
413	                sb.append(String.format("%02X", digest[i]));
414	            }
415	            return sb.toString();
416	        }
417	        catch (NoSuchAlgorithmException e) {
418	            throw new IllegalStateException("SHA-256 not available", e);
419	        }
420	    }
421	}
